  margin: 0 auto;
  padding: 2rem 1rem;
}

.header {
  text-align: center;
  margin-bottom: 2.5rem;
}

.header h1 {
  margin: 0 0 0.5rem 0;
  font-size: 2.5rem;
  color: var(--primary);
}

.header p {
  margin: 0;
  color: var(--text-muted);
  font-size: 1.1rem;
}

.main-content {
  display: grid;
  grid-template-columns: 1fr;
  gap: 2rem;
}

@media (min-width: 768px) {
  .main-content {
    grid-template-columns: 320px 1fr;
  }
}

.card {
  background-color: var(--card-bg);
  border-radius: 8px;
  box-shadow: 0 4px 6px rgba(0, 0, 0, 0.05);
  border: 1px solid var(--border);
  padding: 1.5rem;
}

.form-section h2 {
  margin-top: 0;
  margin-bottom: 1.5rem;
  font-size: 1.3rem;
  border-bottom: 2px solid var(--border);
  padding-bottom: 0.5rem;
}

.bookmark-form {
  display: flex;
  flex-direction: column;
  gap: 1.2rem;
}

.form-group {
  display: flex;
  flex-direction: column;
  gap: 0.4rem;
}

.form-group label {
  font-weight: 600;
  font-size: 0.9rem;
  color: var(--text-muted);
}

.form-group input {
  padding: 0.6rem 0.8rem;
  border: 1px solid var(--border);
  border-radius: 4px;
  font-size: 1rem;
  outline: none;
  transition: border-color 0.2s;
}

.form-group input:focus {
  border-color: var(--primary);
}

.btn {
  padding: 0.75rem 1rem;
  border: none;
  border-radius: 4px;
  font-size: 1rem;
  font-weight: 600;
  cursor: pointer;
  transition: background-color 0.2s;
}

.btn-primary {
  background-color: var(--primary);
  color: white;
}

.btn-primary:hover:not(:disabled) {
  background-color: var(--primary-hover);
}

.btn-primary:disabled {
  opacity: 0.6;
  cursor: not-allowed;
}

.error-msg {
  color: var(--error);
  font-size: 0.9rem;
  margin: 0.5rem 0 0 0;
}

.success-msg {
  color: var(--success);
  font-size: 0.9rem;
  margin: 0.5rem 0 0 0;
}

.bookmarks-section {
  display: flex;
  flex-direction: column;
  gap: 2rem;
}

.filter-bar {
  background-color: var(--card-bg);
  border-radius: 8px;
  padding: 1.5rem;
  border: 1px solid var(--border);
}

.filter-bar h2 {
  margin-top: 0;
  margin-bottom: 1rem;
  font-size: 1.3rem;
}

.tag-cloud {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
  align-items: center;
}

.tag-badge {
  display: inline-flex;
  align-items: center;
  gap: 0.3rem;
  padding: 0.3rem 0.8rem;
  background-color: var(--tag-bg);
  color: var(--tag-text);
  text-decoration: none;
  border-radius: 16px;
  font-size: 0.85rem;
  font-weight: 500;
  transition: all 0.2s;
}

.tag-badge:hover {
  filter: brightness(0.95);
}

.tag-badge.selected {
  background-color: var(--tag-selected-bg);
  color: var(--tag-selected-text);
}

.remove-tag {
  font-weight: bold;
  font-size: 1.1rem;
  line-height: 1;
}

.clear-filters {
  font-size: 0.85rem;
  color: var(--error);
  text-decoration: none;
  margin-left: 0.5rem;
}

.clear-filters:hover {
  text-decoration: underline;
}

.empty-tags {
  color: var(--text-muted);
  font-style: italic;
  margin: 0;
}

.bookmarks-list h2 {
  margin-top: 0;
  margin-bottom: 1.5rem;
  font-size: 1.5rem;
}

.grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 1rem;
}

@media (min-width: 1024px) {
  .grid {
    grid-template-columns: 1fr;
  }
}

.bookmark-item {
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  gap: 1rem;
  transition: transform 0.2s, box-shadow 0.2s;
}

.bookmark-item:hover {
  transform: translateY(-2px);
  box-shadow: 0 6px 12px rgba(0, 0, 0, 0.08);
}

.bookmark-content {
  display: flex;
  flex-direction: column;
  gap: 0.3rem;
}

.bookmark-title {
  margin: 0;
  font-size: 1.2rem;
  color: var(--primary);
}

.bookmark-url {
  color: var(--text-muted);
  text-decoration: none;
  font-size: 0.9rem;
  word-break: break-all;
}

.bookmark-url:hover {
  text-decoration: underline;
}

.bookmark-tags {
  display: flex;
  flex-wrap: wrap;
  gap: 0.4rem;
}

.tag {
  font-size: 0.75rem;
  background-color: #f0f0f0;
  color: #555;
  padding: 0.2rem 0.5rem;
  border-radius: 4px;
  font-weight: 500;
}

.empty-state {
  text-align: center;
  padding: 3rem;
  background-color: var(--card-bg);
  border-radius: 8px;
  border: 1px solid var(--border);
  color: var(--text-muted);
}
